import{_ as l,a0 as o,w as u,s as d,I as n,x as a,a1 as i,A as t,ao as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"怎样在 Ubuntu Linux 中移除 Snap 软件包 | LCTT x X-CMD","titleTemplate":false,"description":"怎样在 Ubuntu Linux 中移除 Snap 软件包 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"怎样在 Ubuntu Linux 中移除 Snap 软件包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"怎样在 Ubuntu Linux 中移除 Snap 软件包 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220428 How to Remove Snap Packages in Ubuntu Linux","title":"怎样在 Ubuntu Linux 中移除 Snap 软件包","tag":"202205","desc":""},"relativePath":"202205/20220428 How to Remove Snap Packages in Ubuntu Linux.md","filePath":"[post].md"}'),r={name:"202205/20220428 How to Remove Snap Packages in Ubuntu Linux.md"};function g(b,s,h,k,f,m){const e=o("Link");return u(),d("div",null,[s[26]||(s[26]=n("h1",{id:"怎样在-ubuntu-linux-中移除-snap-软件包",tabindex:"-1"},[a("怎样在 Ubuntu Linux 中移除 Snap 软件包 "),n("a",{class:"header-anchor",href:"#怎样在-ubuntu-linux-中移除-snap-软件包","aria-label":"Permalink to “怎样在 Ubuntu Linux 中移除 Snap 软件包”"},"​")],-1)),s[27]||(s[27]=n("p",null,[n("img",{src:"https://img.linux.net.cn/data/attachment/album/202205/09/103449pfqp2yp2rpzgp92l.jpg",alt:""})],-1)),s[28]||(s[28]=n("blockquote",null,[n("p",null,"这是一篇关于在 Ubuntu Linux 系统中如何删除 Snap，以得到一个无 Snap 系统的教程。")],-1)),s[29]||(s[29]=n("p",null,"由 Canonical 开发的 Snap 软件包在一些场景下是有益的。它为终端用户直接提供了轻便且快速的程序更新。不仅如此，它还有其他的好处，比如它打包了所有依赖包，并允许安装同一个应用的多个版本。此外，它运行在沙盒模式，提供了安全和其他方面的好处。",-1)),s[30]||(s[30]=n("p",null,"在这些好处中， Snap 技术也有一些地方备受争论。举个例子，几乎所有使用 Snap 软件包的用户都说它的性能较差，包括它的启动时间要比本地 deb 或者 RPM 软件包时间要长。另外，由于它的设计，程序安装的体积巨大，浪费磁盘空间，因为它打包了所有用到的依赖包。",-1)),s[31]||(s[31]=n("p",null,"不仅如此，由于沙盒的天然属性，Snap 程序可能无法访问你的 Linux 桌面的几个部分，除非提供了适当的权限。",-1)),s[32]||(s[32]=n("p",null,"这个指南阐述了你如何从 Ubuntu 系统中完全移除 Snap。",-1)),n("p",null,[s[1]||(s[1]=a("这些步骤在 ",-1)),i(e,{href:"https://www.debugpoint.com/2022/01/ubuntu-22-04-lts/"},{default:t(()=>[...s[0]||(s[0]=[a("Ubuntu 22.04 LTS Jammy Jellyfish",-1)])]),_:1}),s[2]||(s[2]=a(" 中进行了测试。然而，它应该也适用于所有的 Ubuntu 系统版本。",-1))]),s[33]||(s[33]=p(`<blockquote><p><strong>警告：这些步骤将会移除 Ubuntu 系统中两个关键的程序：软件商店和 Firefox。尝试这些步骤之前确认你已经对书签和 Firefox 的其它设置做了备份。</strong></p></blockquote><h3 id="在-ubuntu-linux-移除-snap-软件包" tabindex="-1">在 Ubuntu Linux 移除 Snap 软件包 <a class="header-anchor" href="#在-ubuntu-linux-移除-snap-软件包" aria-label="Permalink to “在 Ubuntu Linux 移除 Snap 软件包”">​</a></h3><p>1、在你的系统中打开一个终端，使用以下命令查看已经安装的 Snap 软件包的列表。它显示了 Snap 软件包，比如 Firefox，软件商店，主题以及其它默认已经安装的核心软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>snap list</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Snap-list-in-Ubuntu.jpg" alt=" Ubuntu Snap 包列表"></p><p>2、按照以下的顺序移除 Snap 软件包。首先移除 Firefox。然后是软件商店，和用以上命令看到的你的系统中的其它软件包。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap remove --purge firefox</span></span>
<span class="line"><span>sudo snap remove --purge snap-store</span></span>
<span class="line"><span>sudo snap remove --purge gnome-3-38-2004</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo snap remove --purge gtk-common-themes</span></span>
<span class="line"><span>sudo snap remove --purge snapd-desktop-integration</span></span>
<span class="line"><span>sudo snap remove --purge bare</span></span>
<span class="line"><span>sudo snap remove --purge core20</span></span>
<span class="line"><span>sudo snap remove --purge snapd</span></span></code></pre></div><p>3、最后，通过 <code>apt</code> 命令移除 Snap 服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt remove --autoremove snapd</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/remove-snap-and-others-1024x544.jpg" alt="移除 Snap 包和其它"></p><p>这还没完，即使你用以上命令移除了 Snap 软件包，但是如果你没有关闭 apt 触发器，<code>sudo apt update</code> 命令会再一次将 Snap 安装回来。</p><p>4、所以，要关闭它，我们需要在 <code>/etc/apt/preferences.d/</code> 目录下创建一个 apt 设置文件 <code>nosnap.pref</code> 来关闭 Snap 服务。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo gedit /etc/apt/preferences.d/nosnap.pref</span></span></code></pre></div><p>5、添加以下的命令行，并保存该文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Package: snapd</span></span>
<span class="line"><span>Pin: release a=*</span></span>
<span class="line"><span>Pin-Priority: -10</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/create-a-pref-file.jpg" alt="创建设置文件"></p><p>如果你知道如何使用它，那么这个 apt 设置文件是一个潜在的工具。举个例子，在以上的状态中，<code>Pin-Priority -10</code> 意思就是阻止 Snap 软件包的安装。</p>`,18)),n("p",null,[s[4]||(s[4]=a("与这个教程不相关的，举个例子，如果你想给所有发行版代号为 “bulleye” 的软件包超高优先权的话，那么就可以查看这些设置文件。如果你想了解更多，你可以访问 ",-1)),i(e,{href:"https://manpages.ubuntu.com/manpages/focal/man5/apt_preferences.5.html"},{default:t(()=>[...s[3]||(s[3]=[a("apt 手册页",-1)])]),_:1}),s[5]||(s[5]=a("。",-1))]),s[34]||(s[34]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Package: *</span></span>
<span class="line"><span>Pin: release n=bullseye</span></span>
<span class="line"><span>Pin-Priority: 900</span></span></code></pre></div><p>6、回到我们的主题，一旦你已经保存和关闭以上文件，从终端中再次运行以下命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update</span></span></code></pre></div><p>7、最后，从 Ubuntu 中移除 Snap 的步骤全部完成。</p><h3 id="从-ubuntu-移除-snap-后使用-deb-文件安装软件商店和-firefox" tabindex="-1">从 Ubuntu 移除 Snap 后使用 deb 文件安装软件商店和 Firefox <a class="header-anchor" href="#从-ubuntu-移除-snap-后使用-deb-文件安装软件商店和-firefox" aria-label="Permalink to “从 Ubuntu 移除 Snap 后使用 deb 文件安装软件商店和 Firefox”">​</a></h3><p>你已经移除了 Firefox 和软件商店，但是你的工作还需要它们。</p><p>要安装 apt 版的 GNOME 软件商店，你可以使用以下命令。确保使用 <code>--install-suggests</code> 参数。否则，将会再次安装上 Snap 版本的软件包管理器！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install --install-suggests gnome-software</span></span></code></pre></div><p>要安装 Firefox，通过以下命令使用官方 PPA 仓库。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository ppa:mozillateam/ppa</span></span>
<span class="line"><span>sudo apt update</span></span>
<span class="line"><span>sudo apt install -t &#39;o=LP-PPA-mozillateam&#39; firefox</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Add-the-PPA-1024x550.jpg" alt="添加 PPA 仓库"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/04/Install-Firefox-as-deb-file-from-PPA-1024x548.jpg" alt="从 PPA 仓库以 deb 文件形式安装 Firefox"></p>`,12)),n("p",null,[s[7]||(s[7]=a("一旦你已经安装完 Firefox，使用以下命令开启自动更新。要了解更多，",-1)),i(e,{href:"https://www.debugpoint.com/2021/09/remove-firefox-snap-ubuntu/"},{default:t(()=>[...s[6]||(s[6]=[a("访问此页",-1)])]),_:1}),s[8]||(s[8]=a("。",-1))]),s[35]||(s[35]=p(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &#39;Unattended-Upgrade::Allowed-Origins:: &quot;LP-PPA-mozillateam:\${distro_codename}&quot;;&#39; | sudo tee /etc/apt/apt.conf.d/51unattended-upgrades-firefox</span></span></code></pre></div><p>最后但同样重要，当运行 <code>apt</code> 时，为 Firefox 创建另一个设置文件给予以上 PPA 仓库超高优先权。如果你不这么做，<code>apt update</code> 命令会再次安装 Snap 版本 Firefox，并把它的“ Snap 朋友们”带回来 😂😂😂。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo gedit /etc/apt/preferences.d/mozillateamppa</span></span></code></pre></div><p>最后，添加这些命令行并保存文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Package: firefox*</span></span>
<span class="line"><span>Pin: release o=LP-PPA-mozillateam</span></span>
<span class="line"><span>Pin-Priority: 501</span></span></code></pre></div><p>完成。</p><h3 id="在-ubuntu-系统恢复到-snap-软件包" tabindex="-1">在 Ubuntu 系统恢复到 Snap 软件包 <a class="header-anchor" href="#在-ubuntu-系统恢复到-snap-软件包" aria-label="Permalink to “在 Ubuntu 系统恢复到 Snap 软件包”">​</a></h3><p>如果你改变想法，移除该设置文件，并通过以下命令再次启动安装程序。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo rm /etc/apt/preferences.d/nosnap.pref</span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade</span></span>
<span class="line"><span>sudo snap install snap-store</span></span>
<span class="line"><span>sudo apt install firefox</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>关于在 Ubuntu 下移除 Snap 软件包做个总结，我想说的是这些处理 Snap 软件包的方法实属无奈。主要是这对新用户来说很困难。我希望这个指南能帮助你处理好 Snap 软件包。完结撒花。</p><hr>`,12)),n("p",null,[s[10]||(s[10]=a("via: ",-1)),i(e,{href:"https://www.debugpoint.com/2022/04/remove-snap-ubuntu/"},{default:t(()=>[...s[9]||(s[9]=[a("https://www.debugpoint.com/2022/04/remove-snap-ubuntu/",-1)])]),_:1})]),n("p",null,[s[16]||(s[16]=a("作者：",-1)),i(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:t(()=>[...s[11]||(s[11]=[a("Arindam",-1)])]),_:1}),s[17]||(s[17]=a(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[12]||(s[12]=[a("lujun9972",-1)])]),_:1}),s[18]||(s[18]=a(" 译者：",-1)),i(e,{href:"https://github.com/hwlife"},{default:t(()=>[...s[13]||(s[13]=[a("hwlife",-1)])]),_:1}),s[19]||(s[19]=a(" 校对：",-1)),i(e,{href:"https://github.com/turbokernel"},{default:t(()=>[...s[14]||(s[14]=[a("turbokernel",-1)])]),_:1}),s[20]||(s[20]=a(", ",-1)),i(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[15]||(s[15]=[a("wxy",-1)])]),_:1})]),n("p",null,[s[23]||(s[23]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[21]||(s[21]=[a("LCTT",-1)])]),_:1}),s[24]||(s[24]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:t(()=>[...s[22]||(s[22]=[a("Linux中国",-1)])]),_:1}),s[25]||(s[25]=a(" 荣誉推出",-1))])])}const P=l(r,[["render",g]]);export{y as __pageData,P as default};
